const express = require('express');
const { trace } = require('@opentelemetry/api');

const app = express();
const tracer = trace.getTracer('api-gateway');

const spanCache = new Map();

app.get('/api/observability/requests/:requestId', (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const spanData = spanCache.get(req.params.requestId);
  if (!spanData) {
    return res.status(404).json({ error: 'Request span not found' });
  }

  // Enforce tenant boundary
  if (spanData.attributes['tenant.id'] !== req.user.tenantId) {
    return res.status(403).json({ error: 'Forbidden: cannot access cross-tenant request spans' });
  }

  // Sanitize authentication secrets from telemetry attributes
  const safeAttributes = { ...spanData.attributes };
  delete safeAttributes['http.request.headers.authorization'];
  delete safeAttributes['tenant.api_key'];

  res.json({
    requestId: req.params.requestId,
    attributes: safeAttributes
  });
});

app.listen(8087);
